import type { Item } from "./data";

export default function EmployeesRow({ item, onToggle }: { item: Item; onToggle: (id: number) => void }) {
  return (
    <div className="flex items-center gap-2">
      <div className="flex-1">
        <span className="font-semibold">
          {item.name}
          {!item.active && <span className="text-gray-500"> (inactivo)</span>}
        </span>
        <span className="ml-2">Sueldo: {item.amount}</span>
      </div>
      <button
        onClick={() => onToggle(item.id)}
        className="px-3 py-1 text-sm bg-blue-500 text-white rounded hover:bg-blue-600"
      >
        Alternar
      </button>
    </div>
